mapper.select:
SELECT a.id,a.status,b.user_code AS usercode,b.name, CASE WHEN b.gender = 1 THEN '男' ELSE '女' END AS sex,b.birth_date AS birthDate,b.mobile,a.CONTENT AS content, c.name AS typename,a.TYPE,a.TERMINAL_ID AS terminalId,d.sos_nos AS sosNos,e.DEVICE_NAME AS devicename, CASE WHEN a.ACCEPT_OPERATOR_ID IS NOT NULL THEN (SELECT user_name FROM yh_user_reginfo WHERE user_code=a.ACCEPT_OPERATOR_ID) ELSE NULL END AS acceptUsername, a.ACCEPT_OPERATOR_ID AS acceptUsercode,
a.ACCEPT_TIME AS acceptTime, a.ACCEPT_DETAIL_DESCRIPTION AS acceptInfo, a.ARCHIVE_TIME AS archiveTime
FROM `yh_he_threshold_alarm` AS a INNER JOIN yh_user_reginfo AS b ON a.MEMBER_ID=b.user_code INNER JOIN yh_he_threshold_type AS c ON a.RECORD_ID=c.id INNER JOIN `yh_user_device` AS d ON a.TERMINAL_ID=d.terminalId INNER JOIN yh_dv_device_type AS e ON e.id=d.terminalType WHERE a.id=#{id}

SELECT a.id,c.user_code AS usercode,c.name,a.TERMINAL_ID AS terminalId,a.type,d.name AS typename, a.CONTENT AS content,a.STATUS AS `status`,a.TIME AS `time` FROM `yh_he_threshold_alarm` AS a INNER JOIN `yh_user_reginfo` AS c ON a.MEMBER_ID=c.user_code INNER JOIN `yh_he_threshold_type` AS d ON a.RECORD_ID=d.id
and c.user_code IN ( SELECT user_code FROM `yh_user_make_card` WHERE doctor=(SELECT id FROM `yh_user_admin_info` WHERE user_code=#{usercode}) AND user_code != '' AND user_code IS NOT NULL )
AND c.name LIKE CONCAT('%',#{nameLike},'%')
AND d.id =#{nametype}
AND a.STATUS=#{status}
AND a.TIME BETWEEN #{strTime} AND #{endTime}
